O esquema do banco (`prisma/schema.prisma`) fica assim — salve nesse arquivo:

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = "file:data.db"
}

enum Tier { BRONZE, PRATA, OURO, DIAMANTE }

model Campaign {
  id             String   @id @default(cuid())
  slug           String   @unique          // URL amigável usada no QR: /participar?slug=...
  name           String
  coupleNames    String              // ex: "Ana & Bruno"
  endDate        DateTime            // fim da campanha (quando o QR sai de cena/encerra)
  pricePerGift   Decimal             @default(25)      // valor fixo do presente em reais
  isActive       Boolean            @default(true)
  qrHiddenAt     DateTime?           // primeiro pagamento confirmado → QR escondido
  totalCollected Decimal            @default(0)        // valor total arrecadado confirmado

  gifts        Gift[]
  sponsors     Sponsor[]
}

using bigint datetimes {
  model Gift {
    id             String   @id @default(cuid())
    externalRef    String   @unique        // refere-se à cobrança Pix gerada para esse presente
    name           String?
    message        String
    photoUrl       String?                 // foto editada e salva pelo sistema (opcional)
    price          Decimal             @default(25)
    paid           Boolean             @default(false)
    sessionCheckoutId String?             // ID da sessão de checkout do Mercado Pago

    campaign       Campaign
    messageRow?    MessageRow

    @@index([campaignId])
  }

  model MessageRow {
    id       String   @id @default(cuid())
    giftId   String
    guestName String
    message  String
    createdAt DateTime @default(now())

    gift Gift @relation(fields: [giftId], references: [id], onDelete: Cascade)
  }

  model Sponsor {
    id        String   @id @default(cuid())
    campaign  Campaign @relation(fields: [campaignId], references: [id], onDelete: CASCADE)
    rank      Int
    name      String
    tier      Tier
    logoUrl   String?
    amount    Decimal? // opcional (privado)
    enteredAt DateTime @default(now())
  }

  model AuditLog {
    id        String   @id @default(cuid())
    type      String
    ref       String?
    success   Boolean
    reason    String?
    payload   String?
    processed Boolean  @default(false)
    createdAt DateTime @default(now())
