import { PrismaClient } from '@prisma/client';

let _dbInstance = null;

export function getDb() {
  if (!_dbInstance) {
    _dbInstance = new PrismaClient();
    _dbInstance.$connect().catch(err => {
      console.error('[db] falha na conexão inicial do Prisma:', err);
      // tenta de novo depois de 5 segundos (útil em hot reload do nodemon)
      setTimeout(() => {
        _dbInstance = new PrismaClient();
        _dbInstance.$connect().catch(console.error);
      }, 5000);
    });
  }
  return _dbInstance;
}

export const db = getDb();
