import { db } from '../db.js';
import axios from 'axios';
import { config } from '../config.js';

// ----------------------------- Sanitização de texto -----------------------------
function cleanText(v, max = 500) {
  if (v == null) return '';
  let s = String(v).trim().replace(/<\w[^>]*>[\s\S]*?</g, ''); // remove blocos <script> etc.
  s = s.replace(/[<>"'{}]/g, c => ({ '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '}': '&#125;' }[c]));
  if (s.length > max) s = s.slice(0, max - 3) + '...';
  return s;
}

// ----------------------------- Mercado Pago (helpers) -----------------------------
const MP = axios.create({ baseURL: config.mercado.baseApi });
function mpAuth() { return { Authorization: `Bearer ${config.mercado.accessToken}` }; }
async function callMp(method, path, body = {}) {
  const url = `/v1${path}`;
  const opts = { method, url, headers: { ...mpAuth(), 'Content-Type': 'application/json' }, ...body };
  try { return await MP.request(opts); }
  catch (e) { throw Object.assign(new Error(`Mercado Pago ${method} ${path}: `), { cause: e }); }
}

