Restante de `messaging.js` — verificação na API e conclusão do pagamento:

```js
// Estados aceitos como "pago" na resposta do Mercado Pago (verifique os valores reais no seu sandbox)
const PAID_STATUSES = new Set(['PAID', 'CONFIRMED', 'COMPLETED', 'SUCCESS']);

export async function verificarTransacaoPorReferencia(reference, payerInfo = {}) {
  // ESTRATÉGIA DE ROBUSTEZ: a CONSULTA DIRETA na API é a fonte da verdade.
  // Mesmo se o webhook chegar torto ou demorar, a consulta acha. Além disso blinda
  // contra webhooks duplicados/fraudulentos.

  try {
    const params = {
      limit: 150, sort: 'DESC', order: 'DESC',
      created_after: new Date(Date.now() - 10 * 60 * 1000).toISOString(),
    };
    const res = await callMp('get', '/transactions', { params, headers: { ...mpAuth() } });
    const txns = (res.data?.transactions || []).reduce((out, t) => {
      const ref = (t.external_ref || t.externalRef || '').replace(/["']/g, '').trim();
      if (ref) out.push({ ...t, ref });
      return out;
    }, []);

    const tx = txns.find(t => t.ref === reference);
    if (!tx) return { found: false, reason: 'transação com essa referência não encontrada' };

    const isPaid = PAID_STATUSES.has(tx.status.toUpperCase())
                  || (tx.payerInfo?.payment_method?.toLowerCase() === 'pix');
    if (!isPaid)
      return { found: true, status: tx.status, warning: `estado "${tx.status}" é ambíguo` };

    return { found: true, status: tx.status, id: tx.id, payer: tx.payerInfo, ref: tx.externalRef };
  } catch (e) {
    // Falha de rede temporária: não bloqueia — registra como fallback e o sistema continua
    console.error('[pix] consulta direta à MP falhou:', e.message);
    return { found: null, fallback: true, error: e.message };
  }
}

export async function salvarAuditLog(entry) {
  // evita processar o mesmo webhook duas vezes
  const jaExiste = await db.auditLog.findFirst({ where: { type: entry.type, ref: entry.ref } });
  if (jaExiste) {
    await db.auditLog.update({
      where: { id: jaExiste.id },
      data: { ...jaExiste, ...entry, updatedAt: new Date() },
    });
  } else {
    await db.auditLog.create({ data: { ...entry, createdAt: new Date() } });
  }
  return jaExiste?.id;
}

export async function concluirPagamento(giftId, payerInfo = {}) {
  const gift = await db.gift.findUniqueOrThrow({ where: { id: giftId } });
  if (gift.paid) return { already: true, gift };

  // 1) Verifica a transação (webhook pode ter chegado duplicado, pode ter falhado etc.)
  const verified = await verificarTransacaoPorReferencia(gift.externalRef, payerInfo);
  if (!verified.found) return { verified: false, reason: 'transação não localizada' };

  const msg = await db.messageRow.findUnique({ where: { giftId }, orderBy: { createdAt: 'desc' } });

  await db.$transaction(async (tx) => {
    // 2) Marca como pago (atômico com a inserção da mensagem)
    await tx.gift.update({
      where: { id: giftId },
      data: { paid: true, updatedAt: new Date() },
    });

    // Oculta o QR somente no PRIMEIRO pagamento confirmado da campanha
    const camp = await tx.campaign.findUnique({ where: { id: gift.campaignId } });
    if (camp && !camp.qrHiddenAt) {
      await tx.campaign.update({
        where: { id: camp.id },
        data: { qrHiddenAt: new Date(), totalCollected: 0 }, // total recalculado depois
      });
    }

    // 3) Insere a mensagem do convidado (só após pagamento confirmado!)
    await tx.messageRow.create({
      data: {
        giftId,
        guestName: payerInfo.name ?? gift.name?.trim() ?? 'Convidado(a)',
        message: cleanText(gift.message),
        createdAt: new Date(),
      },
    });

    // 4) Atualiza o total arrecadado
    const agg = await tx.campaign.aggregate({ where: { id: gift.campaignId }, _sum: { amount: true } });
    const prev = parseFloat(String(agg._sum?.amount ?? 0));
    await tx.campaign.update({
      where: { id: gift.campaignId },
      data: { totalCollected: prev + parseFloat(String(gift.price)) },
    });
  });

  return { confirmed: true, gift, payer: verified.payer, message: msg?.message || '' };
}
```

