(function () {
  'use strict';

  const WS_URL = () => {
    const p = location.protocol;
    return (p === 'https:' ? 'wss:' : 'ws:') + p.slice(7) + '/ws';
  };
  const socket = io(WS_URL(), { transports: ['websocket', 'polling'], reconnection: true });

  // estado de cada aba
  const TABS = [
    { id: 'mensagens', label: '💬 Mensagens', fetch: '/api/messages', q: {} },
    { id: 'patrocinadores', label: '🏆 Patrocinadores', fetch: '/api/sponsors' },
    { id: 'presentes', label: '🎁 Presentes', fetch: '/api/gifts', q: { page: 1, limit: 40 } },
    { id: 'config', label: '⚙️ Configuração', fetch: '/api/config', q: {} },
  ];
  let activeTab = null;

  // ---------- WebSocket ----------
  socket.on('gift:confirmed', (e) => {
    addLiveMessage(e.data.name || '?', e.data.message || '', isOwn(e.data));
  });
  socket.on('counts:update', (e) => {
    if (activeTab === 'config') updateSummary(e.data);
  });

  // ---------- Abas ----------
  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      setActiveTab(btn.dataset.id);
      loadTab(btn.dataset.id);
    });
  });

  document.getElementById('reloadBtn').addEventListener('click', () => window.location.reload());

  function setActiveTab(id) { activeTab = id; }
  function loadTab(id) {
    const t = TABS.find(x => x.id === id);
    if (!t) return;
    const url = t.fetch + '?' + new URLSearchParams(t.q).toString();
    const stored = localStorage.getItem('painel:' + id);
    fetch(url).then(r => r.ok ? r.json() : Promise.reject()).then(data => {
      localStorage.setItem('painel:' + id, JSON.stringify(data));
      const section = document.getElementById('tab-' + id);
      if (section) section.classList.add('active');
      else document.getElementById('app').innerHTML = '<p class="empty">Aberta: ' + t.label + '</p>';
      renderTab(id, data);
    }).catch(() => void (0));
  }

  // ---------- Renderer ----------
  function renderTab(id, data) {
    const s = document.getElementById('tab-' + id);
    if (!s) return;
    s.querySelectorAll('.panel-section').forEach(sec => sec.classList.remove('active'));
    s.querySelectorAll('[data-sect="' + id + '"]').forEach(sec => sec.classList.add('active'));

    switch (id) {
      case 'mensagens': renderMessages(data.messages || []); break;
      case 'patrocinadores': renderSponsors(data || []); break;
      case 'presentes': renderGifts(data?.gifts || []); break;
      case 'config': renderConfig(data || cfgFallback); break;
    }
  }

  // ---------- Mensagens ----------
  function renderMessages(list) {
    const wrp = document.getElementById('msgWrap');
    wrp.innerHTML = '<div class="search-wrap"><input id="msgSearch" placeholder="Buscar por nome ou mensagem…"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg></div><div id="msgList" class="list-wrap"></div>';
    const search = document.getElementById('msgSearch');
    search.addEventListener('input', () => {
      const q = search.value.toLowerCase();
      const items = list.filter(m => (m.name + m.message).toLowerCase().includes(q));
      document.getElementById('msgList').innerHTML = items.map(m => `
        <div class="msg-row" data-gift="${m.id || ''}">
          <div class="msg-name">${esc(m.name)}</div>
          <div class="msg-text">${esc(m.message)}</div>
          <small style="float:right;color:var(--muted)">${new Date(m.time || new Date().toISOString()).toLocaleTimeString('pt-BR')}</small>
        </div>`).join('');
    });
    document.getElementById('msgList').addEventListener('click', e => {
      const el = e.target.closest('.msg-row');
      if (!el) return;
      const g = el.dataset.gift;
      if (!g) return;
      fetch('/api/gifts/' + g).then(r => r.ok ? r.json() : null)
        .then(det => { if (det) window.scrollTo({ top: 0, behavior: 'smooth' }); });
    });
    renderMessages(list);
  }
  function esc(s) { return String(s?.toString() || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

  // ---------- Patrocinadores ----------
  function renderSponsors(sp) {
    const wrap = document.getElementById('sponsorWrap');
    if (!sp.length) { wrap.innerHTML = '<p class="empty">Nenhum patrocinador cadastrado.</p>; return; }
    wrap.innerHTML = sp.slice(0, 12).map(s => `
