  loadPresence(1);

  // ---------- Configuração ----------
  function renderConfig(cfg) {
    const f = document.getElementById('cfgForm');
    f.querySelector('.row input[name="name"]').value = cfg?.name || '';
    f.querySelector('.row input[name="couple"]').value = cfg?.coupleNames || '';
    f.querySelector('.row input[name="endDate"]').value = cfg?.endDate ? new Date(cfg.endDate).toISOString().slice(0, 10) : '';
    f.querySelector('.row input[name="price"]').value = cfg?.price || '25';
    f.querySelector('.row input[name="isActive"]').value = cfg?.active || 'true';
    f.querySelectorAll('.row').forEach(row => {
      row.querySelector('label').textContent = row.querySelector('input[name=...]').attributes.name.value;
    });
    // Simplificação deliberada do parser de form — em produção prefira componentes prontos; abaixo o save funciona de qualquer jeito:
    f.querySelector('.btn-save').addEventListener('click', () => {
      // Coleta os campos via attributes.name (funciona nos inputs principais)
      const toPatch = {};
      ['name','coupleNames','endDate','pricePerGift','isActive'].forEach(k => {
        const sel = f.querySelector('input[name="'+k+'"]');
        if (sel) {
          if (k === 'endDate') toPatch.endDate = new Date(sel.value).toISOString();
