    const el = document.createElement('div');
    el.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);background:#0d1218;color:#fff;border-radius:12px;padding:10px 16px;z-index:999;border:1px solid var(--gold);font-size:.88rem';
    el.textContent = txt; document.body.appendChild(el);
    setTimeout(() => el.remove(), 3000);
  }

  // Inicializa conectando WS e carregando a primeira aba
  function init() {
    connectWs();
    loadTab('patrocinadores');
  }
  function connectWs() {
    if (!ws) return; // já criado no topo
    // o socket global já está ligado; se não, criaríamos aqui — ok para o escopo
  }
  // garante WS conectado
  if (typeof io !== 'undefined') {
    // já existe; apenas aguarda
  }

  // Pequena camada que força a reabertura do socket global se necessário
  let _wsForce = null;
