  // Forçar conexão do socket global se necessário (para receber eventos do telão)
  function forceConnectGlobal() {
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    const s = io(proto + ':' + location.host + '/ws', { transports:['websocket','polling'], reconnection:true, forceNew:true });
    s.on('connect', () => { /* pronto */ });
    // anexa estado global para rastreamento
