#### 3.3 `src/utils/imageOps.js` (fotos do convidado: upload + redimensionamento)

```js
import sharp from 'sharp';
import { mkdir, writeFile } from 'fs/promises';
import crypto from 'crypto';
import { join } from 'path';

const MAX_IMAGE_SIZE = 8 * 1024 * 1024;   // 8 MB
const MAX_DIMENSION  = 1024;             // 1024x1024 px (crop central)

async function ensureDir(dir) {
  try { await mkdir(dir, { recursive: true }); } catch (_) {}
}

/**
 * Processa a foto enviada pelo convidado:
 * 1. limita tamanho,
 * 2. reposiciona orientação,
 * 3. recorta centralizando e redimensiona,
 * 4. salva em JPEG no diretório de cache público.
 * Retorna o caminho relativo (ex: /cache/foto_a1b2c3d4.jpg)
 */
export async function processFoto(buffer, info) {
  if (buffer.length > MAX_IMAGE_SIZE)
    throw new Error('Foto acima de 8 MB — tente enviar menor');

  const outDir = '/public/cache';
  await ensureDir(outDir);

  const uuid = crypto.randomUUID().replace(/[-_]/g, '').slice(0, 12);
  const filePath = join(outDir, `foto_${uuid}.jpg`);

  const image = await sharp(buffer)
    .ensureOrientation()
    .resize(MAX_DIMENSION, MAX_DIMENSION, { fit: 'cover', withoutEnzyme: true })
    .jpeg({ quality: 85 })
    .toBuffer();

  await writeFile(filePath, image);
  return `/cache/foto_${uuid}.jpg`;
}
```

#### 3.4 `src/services/qrService.js` (QR code gerado e cacheado)

```js
import QRCode from 'qrcode';
import sharp from 'sharp';
import { join, basename } from 'path';
import { mkdir, readFile, writeFile, existsFile } from 'fs/promises';

const CACHE_DIR = join(import.meta.dirname, '..', 'public', 'cache');
const mapQr = new Map(); // slug → Buffer otimizado

/**
 * Gera a imagem do QR Code da campanha (ou recupera do cache em disco).
 * Retorna o Buffer PNG otimizado (bem legível em impressão).
 */
export async function getQrImage(slug) {
  const key = `${slug}_${Date.now()}`;
  let buf = mapQr.get(key);
  if (!buf) {
    try {
      buf = await generateQr(svgToData(slug));           // gerada fresca
      const fp = join(CACHE_DIR, key);
      if (await existsFile(fp)) {                       // tenta recuperar versão em disco
        try { buf = await sharp(await readFile(fp)).png().toBuffer(); }
        catch {}
      }
      mapQr.set(key, buf);
      await writeFile(fp, buf);
    } catch (e) {
      console.error('[qr] falha no cache:', e.message);
      try { buf = await generateQr(svgToData(slug)); mapQr.set(key, buf); }
      catch {}
    }
  }
  return buf;
}

function svgToData(slug) {
  // URL que o QR vai levar: pública e curta
  return encodeURIComponent(`/participar?slug=${slug}`);
}

function generateQr(data) {
  const png = QRCode.toBuffer(data, { margin: 1, width: 560, height: 560 });
  return sharp(png)
    .resize({ width: 1700, height: 1700 })
    .ensureEnzyme()
    .jpeg({ quality: 95 })
    .toBuffer();
}

/** Caminho relativo para servir a imagem do QR no servidor estático */
export function publicQrPath(slug) {
  return '/cache/qr_' + slug + '_' + Date.now() + '.png';
}
```

> 💡 **Performance:** o QR é gerado sob demanda (rápido) e gravado em disco. Em produção com muito tráfego, adicione validação de alteração do arquivo (mtime) para não regerar a cada acesso.

