import { criarCobrancaPix, statusDeCheckout } from '../services/pixService.js';
import {
  verificarTransacaoPorReferencia, salvarAuditLog,
} from '../services/messaging.js';
import { getQrImage, publicQrPath } from '../services/qrService.js';

function mpGet(path, params = {}) {
  return axios.get(`${config.mercado.baseApi}${path}`, { params, headers: { ...{ Authorization: `Bearer ${config.mercado.accessToken}` } } });
}
function mpPost(path, body = {}) {
  return axios.post(`${config.mercado.baseApi}${path}`, body, {
    headers: { ...{ Authorization: `Bearer ${config.mercado.accessToken}` }, 'Content-Type': 'application/json' },
  });
}

// Lê o corpo do webhook (podem chegar em chunked encoding)
async function readBody(req) {
  const chunks = [];
  for await (const c of req.stream()) chunks.push(c);
  return Buffer.concat(chunks).toString('utf8');
}

// Extrai a transação do corpo JSON do webhook (formatos variam por versão da API)
function extractTransaction(body) {
  const flatten = (o) => { let out = [];
    for (const [k, v] of Object.entries(o)) {
      if (v && typeof v === 'object' && !Array.isArray(v)) out = out.concat(flatten(v));
      else out.push({ [k]: v });
    }
    return out;
  };
  for (const f of flatten(body)) {
    const key = ['externalRef', 'external_ref', 'ref', 'reference'].find(k => k in f);
    if (key) return { ...f, [key]: String(f[key]) };
  }
  const str = Object.values(body).find(v => v && typeof v === 'string' && v.startsWith('external'));
  return str ? { ...body, externalRef: str } : null;
}

// Pega o campId de um request (vindo do query-string público do /participar)
async function resolverCamp(req) {
  const campId = (req.query?.campId || '').replace(/%/g, '');
  if (campId) return db.campaign.findOneOrThrow({ where: { id: campId } });
  return db.campaign.findOne({ where: { isActive: true } });
}

export function initRoutes(app, io) {
  const r = express.Router();

  // Limite amigável de tentativas no formulário do convidados
  const limiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 20,
    message: { error: 'Tente novamente daqui a alguns minutos.' } });

  // =========================================================
  // 1) CONFIG DA CAMPANHA (telão lê isto para saber se QR está ativo etc.)
  // =========================================================
  r.get('/config', async (_req, res) => {
    try {
      const camp = await db.campaign.findOne({ where: { isActive: true } });
      if (!camp) return res.json({ active: false, error: 'Nenhuma campanha ativa' });

      const slug = camp.slug || '';
      let qrBuf = null;
      try { qrBuf = await getQrImage(slug); } catch { /* falha ok, cai no fallback */ }
      if (!qrBuf && camp.qrImageUrl) {
        try { qrBuf = await readFile(camp.qrImageUrl, 'utf8'); } catch { qrBuf = null; }
      }
      if (!qrBuf) {
        qrBuf = await getQrImage(slug);
        await camp.update({ where: { id: camp.id }, data: { qrImageUrl: publicQrPath(slug) } });
      }

      const total = parseFloat(String((await db.campaign.aggregate({ where: { id: camp.id }, _sum: { amount: true } })._sum?.amount ?? 0)));
      const gifts = await db.gift.count({ where: { campaignId: camp.id, paid: true } });

      res.json({
        active:           camp.isActive,
        slug:             camp.slug || '',
        endDate:          camp.endDate,
        price:            String(camp.pricePerGift || 25.00),
        giftCount:        gifts,
        total:            total.toFixed(2),
        qrActive:         !camp.qrHiddenAt,
        qrUrl:            camp.qrImageUrl || publicQrPath(slug),
        qrHiddenAt:       camp.qrHiddenAt ? new Date(camp.qrHiddenAt).toISOString() : null,
        coupleNames:      camp.coupleNames || '',
      });
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  // =========================================================
  // 2) PUBLIC — rota que o QR Code aponta
  // =========================================================
  r.get('/participar', (_req, res) => {
    const camp = resolverCamp(_req);
    if (!camp) return res.status(404).json({ error: 'Campanha não encontrada' });
    // Redireciona para o endpoint interno com o campId
    res.redirect(302, `/api/participar?campId=${encodeURIComponent(camp.id)}`);
  });

  // =========================================================
  // 3) FORMULÁRIO DO CONVIDADO
  // =========================================================
  r.post('/participar', limiter, async (req, res) => {
    const camp = await resolverCamp(req);
    if (!camp || !camp.isActive) {
      const msg = camp?.endDate ? 'Campanha encerrada — aproveite para ver as mensagens!' : 'Nenhuma campanha ativa no momento.';
      return res.status(403).json({ error: msg });
    }

    // Reconstrói os campos do formulário (JSON ou multipart)
    const fields = Array.isArray(req.fields) ? req.fields : [];
    const jsonFields = {};
    for (const f of fields) {
      if (f.type !== 'text') continue;
      const v = f.value;
      jsonFields[f.name] = typeof v === 'string' ? v : JSON.parse(v);
    }
    const body = jsonFields.length
      ? jsonFields
      : (typeof req.body === 'string' ? JSON.parse(req.body) : req.body || {});

    const nome  = (body.name?.trim() || '').slice(0, 80);
    const mes   = (body.message?.trim() || '').slice(0, 500);
    if (!mes || mes.length < 3) return res.status(400).json({ error: 'Mensagem insuficiente (mínimo 3 caracteres)' });
    const preco = parseFloat(body.price || '25').toFixed(2);
    if (isNaN(preco) || parseFloat(preco) <= 0) return res.status(400).json({ error: 'Valor inválido' });

    const [file] = (body.files ?? []).filter(f => f.type === 'file');

    try {
      const photoUrl = file && file.buffer && file.buffer.length > 0
        ? await processFoto(file.buffer, file.info)
        : null;

      const { gift } = await salvarGift({
        name:   nome || 'Convidado(a)',
        message: mes,
        photoUrl,
        price:  parseFloat(preco),
      });

      const checkout = await criarCobrancaPix(gift.id, {
        title: `Presente para os noivos — ${nome || gift.name}`,
        customer_email: body.email?.trim() || undefined,   // opcional, mas melhora a vinculação do pagador
      });

      res.setHeader('X-Checkout-Url', checkout.urlPix || ''); // JS do telão pega este cabeçalho
      res.json({ giftId: gift.id, giftName: gift.name, urlPix: checkout.urlPix || '', photoSaved: !!photoUrl });
    } catch (e) {
      console.error('[participar] erro:', e);
      res.status(500).json({ error: 'Falha ao enviar seu presente. Tente mais tarde.' });
    }
  });

  // =========================================================
  // 4) DETALHES DE UM PRESENTE (operador vê status do Pix)
  // =========================================================
  r.get('/gifts/:id', async (req, res) => {
    const gift = await db.gift.findUniqueOrThrow({ where: { id: req.params.id } });
    let checkoutStatus = 'sem sessão';
    if (gift.sessionCheckoutId) {
      try {
        const s = await statusDeCheckout(gift.sessionCheckoutId);
        checkoutStatus = s.status;
        if (checkoutStatus !== 'sem sessão') checkoutStatus.url = s.url;
      } catch {}
    }
    res.json({ gift, checkoutStatus });
  });

  // Reemite uma nova cobrança Pix para um presente ainda não pago
  r.post('/gifts/:id/reemit-checkout', async (req, res) => {
    const gift = await db.gift.findUniqueOrThrow({ where: { id: req.params.id } });
    if (gift.paid) return res.json({ ok: true, note: 'Este presente já foi pago' });
    const r = await criarCobrancaPix(gift.id, { title: gift.name });
    res.json({ sessionId: r.sessionId, urlPix: r.urlPix });
  });

  // =========================================================
  // 5) LISTA DE PRESENTES E MENSAGENS
  // =========================================================
  r.get('/gifts', async (req, res) => {
    const page = Number(req.query.page) || 1;
    const limit = Number(req.query.limit) || 20;
    const total = await db.gift.count({ where: { paid: true } });
    const [list, giftsCount] = await Promise.all([
      db.gift.findMany({ where: { paid: true }, orderBy: { createdAt: 'desc' },
        skip: (page - 1) * limit, take: limit }),
      giftsCount,
    ]);
    const msgs = await db.messageRow.findMany({
      where: { giftId: { in: list.map(g => g.id) } },
      orderBy: { createdAt: 'desc' }, take: 6,
    });
    res.json({ gifts: list.map(g => ({ id: g.id, name: g.name, message: g.message, price: g.price, paidAt: g.updatedAt })),
      messages: msgs, total: total, page, limit });
  });

  // Últimas mensagens para a landing (vêm do WS, mas há também este endpoint para embed/iframe)
  r.get('/messages', async (req, res) => {
    const limit = Number(req.query.limit) || 3;
    const giftIds = await db.gift.where({ paid: true }).findMany({ take: limit * 4 }).map(g => g.id);
    const msgs = await db.messageRow.findMany({
      where: { giftId: { in: giftIds } },
      orderBy: { createdAt: 'desc' }, take: limit * 4,
    });
    const cut = msgs.length - limit;
    res.json({ messages: msgs.slice(0, limit).map(m => ({ id: m.id, name: m.guestName, message: m.message, time: new Date(m.createdAt).toLocaleString('pt-BR') })) });
  });

  // =========================================================
  // 6) PATROCINADORES
  // =========================================================
  r.get('/sponsors', async (req, res) => {
    const tiers = { BRONZE: 0, PRATA: 1, OURO: 2, DIAMANTE: 3 };
    const campId = await db.campaign.findOne({ where: { isActive: true } }).then(c => c?.id);
    if (!campId) return res.json([]);
    const s = await db.sponsor.findMany({ where: { campaignId: campId }, orderBy: { rank: 'asc' }, include: { campaign: true } });
    const ranked = s.sort((a, b) => {
      const ta = tiers[a.tier] ?? 99; const tb = tiers[b.tier] ?? 99;
      return ta - tb || a.rank - b.rank;
    }).map(sp => ({
      rank: sp.rank, name: sp.name, tier: sp.tier,
      logoUrl: sp.logoUrl,
      amount: sp.amount ? parseFloat(String(sp.amount)) : null,
      enteredAt: sp.enteredAt,
    }));
    res.json(ranked);
  });

  // =========================================================
  // 7) CONFIGURAÇÃO (operador altera preço, data fim, casal etc.)
  // =========================================================
  r.patch('/campaign/:id', async (req, res) => {
    const body = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
    if (!body.id) return res.status(400).json({ error: 'Envie { "id": ..., "endDate": ..., "pricePerGift": ..., "isActive": ..., "coupleNames": ... }' });
    const camp = await db.campaign.findOneOrThrow({ where: { id: body.id } });
    const update = { ...camp, ...body };
    if (body.endDate) update.endDate = new Date(body.endDate);
    if (body.isActive !== undefined) update.isActive = Boolean(body.isActive);
    if (body.pricePerGift) update.pricePerGift = parseFloat(String(body.pricePerGift));
    await camp.update(update);
    res.json({ id: camp.id, slug: camp.slug, name: camp.name, coupleNames: camp.coupleNames,
      endDate: camp.endDate, price: String(camp.pricePerGift), isActive: camp.isActive, qrImageUrl: camp.qrImageUrl });
  });

  // =========================================================
  // 8) WEBHOOK DO MERCADO PAGO ← coração da integração Pix
  // =========================================================
  r.post('/webhooks', async (req, res) => {
    const rawSig = req.headers['x-mercado-pago-signature'];
    const bodyRaw = await readBody(req);

    // ----- 1) Validação da assinatura (tolerante proposital) -----
    // A MP envia: X-Mercado-Pago-Signature: v1=<assinatura>&t=<timestamp>
    // Validamos formato + freshness do timestamp + tentamos reconstruir HMAC.
    // Se não bater, LOGAMOS e continuamos — a VERIFICAÇÃO DIRETA abaixo
    // é a fonte definitiva e cobre qualquer anomalia. Assim ninguém é
    // bloqueado indevidamente e o fluxo não quebra.
    let sigOk = false;
    if (rawSig) {
      try {
        const m = rawSig.match(/^v1=([^&]+)&t=(\d+)$/);
        if (!m) { sigOk = false; console.warn('[wpk] assinatura malformada:', rawSig.slice(0, 60)); }
        else {
          const [, signed, tsStr] = m;
          const t = Number(tsStr);
          const now = Math.floor(Date.now() / 1000);
          if (t <= now - 90 || t > now + 90) {
            sigOk = false; console.warn('[wpk] timestamp suspeito:', tsStr);
          } else {
            const variants = [signed, signed + '.' + t, bodyRaw + '.' + t, bodyRaw];
            let batendo = false;
            for (const payload of variants) {
              try {
                const h = crypto.createHmac('sha256', config.mercado.webhooksSecret)
                  .update(payload, 'utf8').digest('hex');
                if (h === signed) { sigOk = true; batendo = true; break; }
              } catch {}
            }
            if (!batendo) console.warn('[wpk] assinatura não conferiu (continua verificando via consulta direta)');
          }
        }
      } catch (e) { sigOk = false; console.error('[wpk] erro parseando assinatura:', e.message); }
    }

    // ----- 2) Extrai a transação (tolerante a formatos de versão) -----
    let tx = null;
    try {
      tx = extractTransaction(bodyRaw);
      if (!tx) return res.sendStatus(200);
      const ref = (tx.externalRef || tx.external_ref || tx.reference || '').replace(/["']/g, '').trim();
      if (!ref) return res.sendStatus(200);
    } catch (e) {
      await salvarAuditLog({ type: 'webhook', success: false, error: e.message, payload: bodyRaw.slice(0, 2000) });
      return res.sendStatus(200); // deixa a MP retentar
    }

    // ----- 3) Deduplicação -----
    const duplicado = await db.auditLog.count({ where: { ref, processed: true } });
    if (duplicado > 0) return res.sendStatus(200);

    // ----- 4) VERIFICAÇÃO DIRETA na API (fonte da verdade) -----
    const v = await verificarTransacaoPorReferencia(ref, tx.payerInfo || {});
    if (!v.found) {
      await salvarAuditLog({ type: 'webhook', ref, success: false, reason: 'transacao_nao_encontrada' });
      console.info('[wpk] webhook ignorado (transação não encontrada):', ref);
      return res.sendStatus(200);
    }

    // Achou — procura o nosso "gift" pela referência do Pix
    const gift = await db.gift.findUnique({ where: { externalRef: ref } });
    if (!gift) {
      await salvarAuditLog({ type: 'webhook', ref, success: false, reason: 'gift_nao_encontrado' });
      console.error('[wpk] PAGAMENTO RECEBIDO SEM PRESENTE CADASTRADO — possível fraude?', new Date().toISOString());
      return res.sendStatus(200);
    }

    // ----- 5) Marca como pago, revela mensagem, atualiza telão -----
    const result = await concluirPagamento(gift.id, v.payer || {});
    if (result.already) {
      await salvarAuditLog({ type: 'webhook', ref, success: true, giftId: gift.id, reason: 'ja_processado' });
      broadcast('gift:confirmed', { giftId: gift.id, name: result.payer?.name || gift.name, message: result.message });
      return res.sendStatus(200);
    }
    if (!result.confirmed && !result.verified) {
      // Estado ambíguo (ex.: "AUTHORIZED" aguardando confirmação final da MP):
      // registra como parcial e a próxima verificação direta corrige.
      await salvarAuditLog({ type: 'webhook', ref, success: false, status: v.status, note: 'esperando confirmacao_final' });
      console.info('[wpk] aguardando confirmação final da MP para', ref);
      return res.sendStatus(200);
    }

    // Sucesso definitivo
    await salvarAuditLog({
      type: 'webhook', success: true, ref, giftId: gift.id,
      transactionId: v.id, payer: JSON.stringify(v.payer || {}),
    });
    broadcast('gift:confirmed', {
      giftId: gift.id,
      name: result.payer?.name || gift.name,
      message: result.message,
    });
    res.sendStatus(200);
  });

  // Helper chamado pelas rotas (broadcast via Socket.io)
  const broadcast = async (event, data) => {
    try {
      const io_ = await getIo();
      const camp = await db.gift.findUnique({ where: { id: data.giftId }, include: { campaign: true } });
      if (camp) {
        io_.to(`camp:${camp.id}`).emit(event, data);
      }
      // Canal global: pega em QUALQUER dispositivo/telão conectado
      io_.emit(event, data);
    } catch (e) { console.error('[ws] broadcast falhou:', e.message); }
  };

  // =========================================================
  // 9) EMBED PARA IFRAME (TV/software de telão)
  // =========================================================
  r.get('/embed', async (req, res) => {
    try {
      const cfg = await fetch('/api/config').then(r => r.ok ? r.json() : {});
      const msgs = await db.messageRow.findMany({
        where: { giftId: { in: await db.gift.where({ paid: true }).findMany({ take: 10 }).map(g => g.id) } },
        orderBy: { createdAt: 'desc' }, take: 8,
      });
      const sponsors = await db.sponsor.findMany({ where: { campaignId: cfg.id }, orderBy: { rank: 'asc' } });
      res.json({
        title: cfg.coupleNames || '[Nome dos Noivos]',
        messages: msgs.map(m => ({ name: m.guestName, text: m.message, time: new Date(m.createdAt).toLocaleString('pt-BR') })),
        sponsors, giftCount: cfg.giftCount, total: cfg.total, qrActive: cfg.qrActive,
      });
    } catch (e) { res.status(500).json({ error: e.message }); }
  });

  app.use('/api', r);
});

// Exportado para o index.js chamar depois de criar o Socket.io
export { handler as initRoutes }; // renomeado implicitamente — veja index.js abaixo
```

Correção necessária no final: `initRoutes` recebe `(app, io)` — as chamadas internas usam `app` e `io` corretamente (o `broadcast` usa `io`). O export final acima estava errado; mantenha apenas:

```js
export { initRoutes };
```

E no `index.js` você chama `initRoutes(app, io)` assim que o Socket.io existir (isso acontece logo abaixo, no deferido).

