#### `public/js/landing.js` (lógica do telão)

```js
(function () { 'use strict';

  const STORAGE = 'cp_cfg_v1';
  let cfg = null;
  let ws = null;
  let myGiftId = localStorage.getItem('myGiftId');   // reconhecimento do próprio presente

  // ---------- Carrega a configuração da campanha ----------
  async function loadConfig() {
    try {
      const r = await fetch('/api/config', { credentials: 'same-origin' });
      if (!r.ok) return null;
      cfg = await r.json();
      localStorage.setItem(STORAGE, JSON.stringify(cfg));
      if (!cfg.qrActive) markEnded();
      updateAll();
    } catch (e) { console.warn('[cp] não carregou config inicial:', e); return null; }
  }

  function updateAll() {
    injectCouple();
    document.getElementById('priceDisplay').textContent = cfg?.price.replace('.', ',');
    document.getElementById('counterGifts').textContent = Intl.NumberFormat('pt-BR').format(cfg?.giftCount || 0);
    document.getElementById('counterTotal').textContent = brl(cfg?.total || 0);
    countdown(cfg?.endDate);
    drawSponsors(cfg?.sponsors || []);
    if (!cfg?.qrActive) hideQr();
  }

  function brl(v) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v); }

  function injectCouple() {
    document.getElementById('coupleText').textContent = cfg?.coupleNames || '[NOME COMPLETO DOS NOIVOS]';
  }

  // ---------- Contador regressivo ----------
  function countdown(end) {
    const el = document.getElementById('timerEl');
    if (!end || end.getTime() <= 0) { el.style.display = 'none'; return; }
    let d = end - Date.now();
    d = Math.max(0, d);
    const h = Math.floor(d / 3600000), m = Math.floor((d % 3600000) / 60000), s = Math.floor((d % 60000) / 1000);
    el.textContent = `${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m ${String(s).padStart(2,'0')}s`;
    clearTimeout(window.__cpTimer__);
    window.__cpTimer__ = setInterval(countdown, 10000);
  }

  // ---------- Socket.io (atualizações ao vivo) ----------
  function connectWs() {
    if (!cfg) return;
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    ws = io(`${proto}:${location.host}/ws`, {
      transports: ['websocket', 'polling'],           // polling como fallback se WS falhar
      reconnection: true, reconnectionDelay: 800,
      maxReconnectionDelay: 8000, reconnectionAttempts: 20,
      timeout: 12000, forceNew: true,
      query: { sid: localStorage.getItem('wsSid') },   // reabre sessão antiga se possível
    });
    ws.on('connect', () => { console.log('[cp] WebSocket ligado ✔'); startListeners(); });
    ws.on('disconnect', () => console.warn('[cp] WebSocket desconectado ✖'));
    ws.on('error',  (e) => console.error('[cp] erro ws:', e.message));
    ws.on('connect_error', e => {
      console.error('[cp] falha conexão WS:', e.message);
      if (!ws || !ws.connected) setTimeout(connectWs, 2000); // evita loop infinito
    });
  }

  function startListeners() {
    if (!ws) return;
    ws.on('gift:confirmed', revealMessage);
    ws.on('qr:hide',   hideQr);
    ws.on('counts:update', (e) => {
      const d = e.data;
      document.getElementById('counterGifts').textContent = Intl.NumberFormat('pt-BR').format(d.giftCount);
      document.getElementById('counterTotal').textContent = brl(d.total);
      countdown(cfg.endDate);
    });
  }

  // ---------- Revelar mensagem recebida ----------
  function revealMessage(ev) {
    const m = ev.data || {};
    const name = m.name || m.guestName || 'Convidado(a)';
    const isMine = myGiftId && String(m.giftId) === myGiftId;
    const msgEl = document.getElementById('msgList');
    if (msgEl.children.length >= 30) msgEl.lastChild.remove(); // evita poluição

    const row = document.createElement('div');
    row.className = 'msg-row';
    const who = document.createElement('div');
    who.className = 'msg-name';
    who.textContent = name;
    if (isMine) who.style.color = '#ffd966';
    const txt = document.createElement('div');
    txt.className = 'msg-text';
    txt.textContent = m.message || '';
    const flash = document.createElement('div');
    flash.className = 'msg-flash';
    flash.textContent = isMine ? '✨ É SUA MENSAGEM 👏' : '💚 Recém-revelada';
    flash.style.animation = isMine ? 'sparkle 1.5s ease infinite' : 'glow 1.6s ease-in infinite';
    row.appendChild(who); row.appendChild(txt); row.appendChild(flash);
    msgEl.prepend(row);

    const ind = document.getElementById('liveIndicator');
    ind.className = isMine ? 'indicator active mine' : 'indicator';
    ind.textContent = isMine ? '🎉 Você apareceu no telão!' : 'Mensagem recém-revelada';

    if (isMine) {
      localStorage.setItem('myGiftId', m.giftId);
      setTimeout(() => {
        const box = document.getElementById('payBox');
        if (box && box.dataset.id === String(m.giftId)) {
          box.textContent = '';
          box.dataset.giftId = m.giftId;
          box.appendChild(document.createElement('br'));
          box.appendChild(document.createTextNode(m.message));
        }
      }, 1200);
    }
  }

  // ---------- Esconde o QR após o primeiro pagamento ----------
  function hideQr() {
    const z = document.getElementById('qrZone');
    z.classList.add('qr-hidden');
    // mantém contadores e mensagens visíveis
  }

  function markEnded() {
    const z = document.getElementById('qrZone');
    z.classList.add('qr-hidden');
    const form = document.getElementById('formWrap');
    form.classList.add('ended');
    form.querySelector('#sendBtn').disabled = true;
    document.querySelector('.formwrap.h3').insertAdjacentHTML('afterend',
      '<p style="margin:12px 0 0;text-align:center;color:var(--muted);font-size:.9rem">' +
      'A campanha acabou. Deixe aqui suas mensagens mesmo sem pagamento, ou assista ao replay.' + '</p>');
  }

  // ---------- Área do QR ----------
  async function loadQr() {
    if (!cfg) return;
    const img = document.getElementById('qrImg');
    try {
      const r = await fetch(cfg.qrUrl);
      if (r.ok) img.src = await r.text();
      else img.src = ''; // fallback (deverá sempre existir)
    } catch (e) { console.warn('[cp] falhou ao carregar QR:', e); }
  }
  window.addEventListener('load', loadQr);
  // recarrega se o QR foi regeratado no servidor (a cada visita/edição)
  setInterval(loadQr, 300000);

  // =================== INTERATIVIDADE DO FORMULÁRIO ===================
  const formWrap = document.getElementById('formWrap');
  const nomeI   = document.getElementById('nome');
  const mesI    = document.getElementById('mensagem');
  const envioEl = document.getElementById('sendBtn');
  const okDiv   = document.getElementById('formOk');
  const errDiv  = document.getElementById('formError');
  let ctrlSubmit = false;

  mesI.addEventListener('keydown', e => {
    if (e.ctrlKey && e.key === 'Enter') { e.preventDefault(); doSubmit(); };
  });

  function doSubmit() {
    if (ctrlSubmit || !formWrap.classList.contains('ended')) {
      showError('A campanha encerrou ou há algum problema. Tente novamente.');
      return;
    }
    ctrlSubmit = true;
    envioEl.disabled = true;
    envioEl.textContent = 'Enviando…';

    const fd = new FormData(formWrap);
    fetch('/api/participar', { method: 'POST', body: fd, credentials: 'same-origin' })
      .then(r => {
        if (!r.ok) {
          envioEl.disabled = false; envioEl.textContent = 'Enviar mensagem + presente';
          const est = r.status + ' — ' + r.statusText;
          errDiv.style.display = 'block'; errDiv.textContent = est;
          return null;
        }
        errDiv.style.display = 'none';
        okDiv.style.display = 'block';
        const res = r.json();
        localStorage.setItem('myGiftId', res.giftId);
        const box = document.getElementById('payBox');
        if (box) {
          box.textContent = ''; box.dataset.id = res.giftId;
          const mono = document.createElement('textarea');
          mono.rows = 2; mono.cols = 30; mono.style.fontFamily = 'monospace'; mono.style.wordBreak = 'break-all';
          mono.value = res.urlPix;
          box.appendChild(mono);
          box.setAttribute('readonly', 'readonly');
        }
        return res.urlPix;
      })
      .then(urlPix => {
        if (urlPix) showPaymentModal(urlPix);
        okDiv.style.display = 'none';
        ctrlSubmit = false;
      })
      .catch(() => {
        envioEl.disabled = false; envioEl.textContent = 'Enviar mensagem + presente';
        errDiv.style.display = 'block'; errDiv.textContent = 'Falha no envio. Abra novamente e tente mais tarde.';
        ctrlSubmit = false;
      });
  }

  // Botão enviar
  document.getElementById('sendBtn').addEventListener('click', doSubmit);

  // ---------- Modal de pagamento ----------
  const payModal = document.getElementById('payModal');
  const overlay  = document.getElementById('modalOverlay');
  const payPane  = document.getElementById('payPane');
  let currentPixUrl = null;

  function showPaymentModal(urlPix, giftId) {
    const nome = document.getElementById('payGiftName');
    const box  = document.getElementById('payBox');
    const stat = document.getElementById('payStatus');
    nome.textContent = 'Presente para os noivos — ' + (localStorage.getItem('giftName') || 'Convidado(a)');
    box.dataset.id = giftId || '';
    stat.textContent = '';
    document.getElementById('closePay').textContent = '';

    overlay.addEventListener('click', () => closePay());
    payModal.addEventListener('keydown', e => { if (e.key === 'Escape') closePay(); });
  }

  function closePay() {
    payModal.classList.remove('open');
    overlay.removeEventListener('click', () => closePay());
  }

  document.getElementById('closePay').addEventListener('click', closePay);
  document.getElementById('openBtn').addEventListener('click', () => {
    if (!currentPixUrl) return;
    window.open(currentPixUrl, '_blank');
    alert('Abriu o pagamento no app/banco. Aguarde a confirmação para ver sua mensagem no telão.');
  });

  document.getElementById('copyBtn').addEventListener('click', async () => {
    if (!currentPixUrl) return;
    try {
      await navigator.clipboard.writeText(currentPixUrl);
      const t = document.getElementById('payBox');
      t.style.borderColor = '#6bff6b';
      setTimeout(() => t.style.borderColor = '', 1800);
      showToast('Link copiado! Cole no app do seu banco/carteira e pague por Pix.');
    } catch (err) {
      // fallback sem clipboard API
      const ta = document.createElement('textarea');
      ta.value = currentPixUrl; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select;
      document.execCommand('copy');
      document.body.removeChild(ta);
      showToast('Link copiado! Cole no app do seu banco/carteira e pague por Pix.');
    }
  });

  function showToast(txt) {
    const el = document.createElement('div');
    el.style.cssText = 'position:fixed;left:50%;bottom:20%;transform:translateX(-50%);background:rgba(20,28,43,.95);color:#fff;border-radius:12px;padding:10px 16px;z-index:999;border:1px solid var(--gold);font-size:.88rem';
    el.textContent = txt; document.body.appendChild(el);
    setTimeout(() => { el.style.transition = 'opacity .4s'; el.style.opacity = '0';
      setTimeout(() => el.remove(), 400); }, 3200);
  }

  // Abre o formulário se estiver escondido (caso alguém abra direto a landing)
  if (!formWrap.style.display) {
    // se o QR estiver ativo, mostra um banner discreto informando
    const banner = document.createElement('div');
    banner.style.cssText = 'position:fixed;top:0;left:0;right:0;padding:10px 16px;text-align:center;background:rgba(242,194,75,.12);color:var(--gold);font-size:.85rem;z-index:1000';
    banner.textContent = '👉 Escaneie o QR Code para enviar sua mensagem e presente.';
    document.getElementById('layout').insertBefore(banner, document.querySelector('.hero'));
  }

  // Carrega config e conecta WS na primeira interação relevante
  loadConfig();
  if (cfg?.qrActive) connectWs();
  // Também conecta WS caso alguém já esteja navegando na página
  if (!ws && cfg) connectWs();

})();
