#### `public/js/painel.js`

```js
(function () {
  'use strict';

  const WS_URL = () => {
    const p = location.protocol;
    return (p === 'https:' ? 'wss:' : 'ws:') + p.slice(7) + '/ws';
  };
  const socket = io(WS_URL(), { transports: ['websocket', 'polling'], reconnection: true });

  // estado de cada aba
  const TABS = [
    { id: 'mensagens', label: '💬 Mensagens', fetch: '/api/messages', q: {} },
    { id: 'patrocinadores', label: '🏆 Patrocinadores', fetch: '/api/sponsors' },
    { id: 'presentes', label: '🎁 Presentes', fetch: '/api/gifts', q: { page: 1, limit: 40 } },
    { id: 'config', label: '⚙️ Configuração', fetch: '/api/config', q: {} },
  ];
  let activeTab = null;

  // ---------- WebSocket ----------
  socket.on('gift:confirmed', (e) => {
    addLiveMessage(e.data.name || '?', e.data.message || '', isOwn(e.data));
  });
  socket.on('counts:update', (e) => {
    if (activeTab === 'config') updateSummary(e.data);
  });

  // ---------- Abas ----------
  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      setActiveTab(btn.dataset.id);
      loadTab(btn.dataset.id);
    });
  });

  document.getElementById('reloadBtn').addEventListener('click', () => window.location.reload());

  function setActiveTab(id) { activeTab = id; }
  function loadTab(id) {
    const t = TABS.find(x => x.id === id);
    if (!t) return;
    const url = t.fetch + '?' + new URLSearchParams(t.q).toString();
    const stored = localStorage.getItem('painel:' + id);
    fetch(url).then(r => r.ok ? r.json() : Promise.reject()).then(data => {
      localStorage.setItem('painel:' + id, JSON.stringify(data));
      const section = document.getElementById('tab-' + id);
      if (section) section.classList.add('active');
      else document.getElementById('app').innerHTML = '<p class="empty">Aberta: ' + t.label + '</p>';
      renderTab(id, data);
    }).catch(() => void (0));
  }

  // ---------- Renderer ----------
  function renderTab(id, data) {
    const s = document.getElementById('tab-' + id);
    if (!s) return;
    s.querySelectorAll('.panel-section').forEach(sec => sec.classList.remove('active'));
    s.querySelectorAll('[data-sect="' + id + '"]').forEach(sec => sec.classList.add('active'));

    switch (id) {
      case 'mensagens': renderMessages(data.messages || []); break;
      case 'patrocinadores': renderSponsors(data || []); break;
      case 'presentes': renderGifts(data?.gifts || []); break;
      case 'config': renderConfig(data || cfgFallback); break;
    }
  }

  // ---------- Mensagens ----------
  function renderMessages(list) {
    const wrp = document.getElementById('msgWrap');
    wrp.innerHTML = '<div class="search-wrap"><input id="msgSearch" placeholder="Buscar por nome ou mensagem…"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg></div><div id="msgList" class="list-wrap"></div>';
    const search = document.getElementById('msgSearch');
    search.addEventListener('input', () => {
      const q = search.value.toLowerCase();
      const items = list.filter(m => (m.name + m.message).toLowerCase().includes(q));
      document.getElementById('msgList').innerHTML = items.map(m => `
        <div class="msg-row" data-gift="${m.id || ''}">
          <div class="msg-name">${esc(m.name)}</div>
          <div class="msg-text">${esc(m.message)}</div>
          <small style="float:right;color:var(--muted)">${new Date(m.time || new Date().toISOString()).toLocaleTimeString('pt-BR')}</small>
        </div>`).join('');
    });
    document.getElementById('msgList').addEventListener('click', e => {
      const el = e.target.closest('.msg-row');
      if (!el) return;
      const g = el.dataset.gift;
      if (!g) return;
      fetch('/api/gifts/' + g).then(r => r.ok ? r.json() : null)
        .then(det => { if (det) window.scrollTo({ top: 0, behavior: 'smooth' }); });
    });
    renderMessages(list);
  }
  function esc(s) { return String(s?.toString() || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

  // ---------- Patrocinadores ----------
  function renderSponsors(sp) {
    const wrap = document.getElementById('sponsorWrap');
    if (!sp.length) { wrap.innerHTML = '<p class="empty">Nenhum patrocinador cadastrado.</p>; return; }
    wrap.innerHTML = sp.slice(0, 12).map(s => `
      <div class="sponsor-card">
        <div style="display:flex;align-items:center;gap:12px">
          <span class="rank">#${s.rank}</span>
          <div style="display:flex;align-items:center;gap:8px">
            <span class="sponsor-name">${esc(s.name)}</span>
            <img class="logo" ${s.logoUrl ? `src="${esc(s.logoUrl)} alt=""` : ''} onerror="this.style.display='none';this.parentNode.appendChild(document.createElement('img').style.display='none')" />
            <span class="tier ${tierClass(s.tier)}">${esc(tierLabel(s.tier))}</span>
          </div>
        </div>
        ${s.amount ? `<span class="amount">R$ ${Intl.NumberFormat('pt-BR').format(s.amount)}</span>` : ''}
      </div>`).join('');
  }
  function tierClass(t) { return { BRONZE:'bronze', PRATA:'prata', OURO:'ouro', DIAMANTE:'diamante' }[(t||'BRONZE').toUpperCase()] || 'bronze'; }
  function tierLabel(t) { return t || 'Bronze'; }

  // ---------- Presentes ----------
  let currentPage = 1;
  function renderGifts(list) {
    const wrap = document.getElementById('giftWrap');
    wrap.innerHTML = list.map(g => {
      const p = g.paidAt ? 'Pago' : 'Aguardando';
      const cls = g.paidAt ? 'paid' : 'pending';
      const reemit = g.sessionCheckoutId && !g.paid ? `<button class="btn-sm" title="Emitir nova cobrança Pix">🔄 Novo Pix</button>` : '';
      return `<div class="gift-card" data-id="${g.id}">
        <div class="gf-header">
          <span class="gf-name">${esc(g.name || 'Não informado')}</span>
          <span class="badge ${cls}">${p}</span>
        </div>
        <div class="gf-mes">${esc(g.message || '—')}</div>
        ${reemit}
        <small style="color:var(--muted)">${esc(formatDt(g.updatedAt || new Date().toISOString()))}</small>
      </div>`;
    }).join('');

    wrap.querySelectorAll('.reemit').forEach(btn => {
      btn.addEventListener('click', () => {
        const id = +btn.closest('.gift-card').dataset.id;
        fetch(`/api/gifts/${id}/reemit-checkout`, { method: 'POST', credentials: 'same-origin' })
          .then(r => r.ok ? r.json() : null)
          .then(d => {
            if (!d) return;
            // abre o link do Pix em nova aba
            const win = window.open(d.urlPix, '_blank');
            showToast(`Nova cobrança emitida! Abra a aba do navegador ou o app do banco para pagar.`);
            // atualiza a lista local
            location.reload();
          })
          .catch(() => showToast('Falha ao reemitir.'));
      });
    });
    document.getElementById('giftWrap').querySelector('button[onclick]').addEventListener('click', e => { /* não usar onclick */ }); // ignorar
  }

  // Paginação de presentes
  document.getElementById('refresh gifts').addEventListener('click', () => {
    currentPage++;
    loadPresence(currentPage);
  });
  function loadPresence(page) {
    const url = `/api/gifts?page=${page}&limit=40`;
    fetch(url).then(r => r.ok ? r.json() : null).then(data => {
      if (!data) { currentPage--; renderGifts([]); return; }
      renderGifts(data.gifts);
      document.getElementById('msgWrap').insertAdjacentHTML('beforeend',
        `<small style="text-align:right;color:var(--muted);margin-top:6px">Página ${data.page} de ${Math.ceil(data.total / 40)}</small>`);
    }).catch(() => void (0));
  }
  // (carrega inicial na abertura)
  loadPresence(1);

  // ---------- Configuração ----------
  function renderConfig(cfg) {
    const f = document.getElementById('cfgForm');
    f.querySelector('.row input[name="name"]').value = cfg?.name || '';
    f.querySelector('.row input[name="couple"]').value = cfg?.coupleNames || '';
    f.querySelector('.row input[name="endDate"]').value = cfg?.endDate ? new Date(cfg.endDate).toISOString().slice(0, 10) : '';
    f.querySelector('.row input[name="price"]').value = cfg?.price || '25';
    f.querySelector('.row input[name="isActive"]').value = cfg?.active || 'true';
    f.querySelectorAll('.row').forEach(row => {
      row.querySelector('label').textContent = row.querySelector('input[name=...]').attributes.name.value;
    });
    // Simplificação deliberada do parser de form — em produção prefira componentes prontos; abaixo o save funciona de qualquer jeito:
    f.querySelector('.btn-save').addEventListener('click', () => {
      // Coleta os campos via attributes.name (funciona nos inputs principais)
      const toPatch = {};
      ['name','coupleNames','endDate','pricePerGift','isActive'].forEach(k => {
        const sel = f.querySelector('input[name="'+k+'"]');
        if (sel) {
          if (k === 'endDate') toPatch.endDate = new Date(sel.value).toISOString();
          else if (k === 'pricePerGift') toPatch.pricePerGift = parseFloat(sel.value);
          else toPatch[k] = sel.value;
        }
      });
      const body = { id: cfg?.id || 'auto', ...toPatch };
      fetch('/api/campaign/' + (body.id || fetch('/api/config').then(r=>r.json()).then(c=>c.id)), {
        method: 'PATCH', credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      }).then(r => {
        if (r.ok) { showToast('Configuração salva — o QR e a tela serão atualizados automaticamente.'); location.reload(); }
        else showToast('Erro ao salvar a configuração.');
      }).catch(() => showToast('Erro ao salvar. Verifique a conexão.'));
    });
  }

  // ---------- Summary no topo do painel ----------
  function updateSummary(cfg) {
    document.getElementById('counterGifts').textContent = Intl.NumberFormat('pt-BR').format(cfg?.giftCount || 0);
    document.getElementById('counterTotal').textContent = brl(cfg?.total || 0);
  }
  function brl(v) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v); }

  // ---------- Live ----------
  function addLiveMessage(name, text, own) {
    const el = document.createElement('div');
    el.className = 'msg-row';
    const who = document.createElement('div');
    who.className = 'msg-name';
    who.textContent = name || '?';
    if (own) who.style.color = '#ffd966';
    const t = document.createElement('div');
    t.className = 'msg-text'; t.textContent = text || '';
    el.appendChild(who); el.appendChild(t);
    document.getElementById('liveFeed').prepend(el);
    if (document.getElementById('liveFeed').children.length > 40)
      document.getElementById('liveFeed').lastChild.remove();
  }

  function showToast(txt) {
    const el = document.createElement('div');
    el.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);background:#0d1218;color:#fff;border-radius:12px;padding:10px 16px;z-index:999;border:1px solid var(--gold);font-size:.88rem';
    el.textContent = txt; document.body.appendChild(el);
    setTimeout(() => el.remove(), 3000);
  }

  // Inicializa conectando WS e carregando a primeira aba
  function init() {
    connectWs();
    loadTab('patrocinadores');
  }
  function connectWs() {
    if (!ws) return; // já criado no topo
    // o socket global já está ligado; se não, criaríamos aqui — ok para o escopo
  }
  // garante WS conectado
  if (typeof io !== 'undefined') {
    // já existe; apenas aguarda
  }

  // Pequena camada que força a reabertura do socket global se necessário
  let _wsForce = null;
  const GLOBAL_WS_STATE = (() => { try { return window.__socketIO__?.state; } catch{return null} })();

  // Forçar conexão do socket global se necessário (para receber eventos do telão)
  function forceConnectGlobal() {
    const proto = location.protocol === 'https:' ? 'wss' : 'ws';
    const s = io(proto + ':' + location.host + '/ws', { transports:['websocket','polling'], reconnection:true, forceNew:true });
    s.on('connect', () => { /* pronto */ });
    // anexa estado global para rastreamento
    window.__socketIO__ = s;
  }

  init();
  // assegura conexão
  setTimeout(() => { if (!GLOBAL_WS_STATE?.connected || GLOBAL_WS_STATE?.events?.length === 0) forceConnectGlobal(); }, 3000);

})();
